                .map(|end| end.lookup_remaining_seconds(now))
                .transpose()
                .map_err(|_| denied())?
                .unwrap_or(0)
        );
        info["expire_time"] = json!(lease.expires_at.map(Timestamp::local_rfc3339).transpose()?);
